<?php
require 'includes/db.php';
session_start();
$id=(int)($_GET['id']??0);$s=null;$saved=false;
if($id){$q=$pdo->prepare('SELECT * FROM scholarships WHERE id=?');$q->execute([$id]);$s=$q->fetch();if(!$s)$id=0;if($s&&!empty($_SESSION['student_id'])){$q=$pdo->prepare('SELECT id FROM student_favourites WHERE student_id=? AND scholarship_id=?');$q->execute([$_SESSION['student_id'],$id]);$saved=(bool)$q->fetch();}}
$search=trim($_GET['search']??'');$cat=$_GET['category']??'';$course=$_GET['course']??'';
if(!$id){$w=[];$p=[];if($search){$w[]='(name LIKE ? OR department LIKE ? OR eligibility LIKE ? OR course LIKE ?)';$x="%$search%";$p=[$x,$x,$x,$x];}if($cat){$w[]='category=?';$p[]=$cat;}if($course){$w[]='course=?';$p[]=$course;}$sql='SELECT * FROM scholarships'.($w?' WHERE '.implode(' AND ',$w):'').' ORDER BY id';$q=$pdo->prepare($sql);$q->execute($p);$items=$q->fetchAll();}
function scholarship_status($deadline){if(!$deadline)return ['Deadline not set','status-neutral'];$today=new DateTimeImmutable('today');$d=new DateTimeImmutable($deadline);$days=(int)$today->diff($d)->format('%r%a');if($days<0)return ['Closed','status-closed'];if($days<=30)return ['Closing Soon','status-soon'];return ['Open','status-open'];}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Scholarships | ScholarConnect Pro</title><link rel="stylesheet" href="css/style.css"></head><body><?php include 'includes/header.php'; ?><header class="page-header"><span class="eyebrow">SCHOLARSHIP DIRECTORY</span><h1><?=$id?'Scholarship Details':'Explore Maharashtra Scholarships'?></h1><p>Use the filters to find schemes, then verify current information on MahaDBT.</p></header><section class="directory"><?php if($id):$st=scholarship_status($s['deadline']??null);?><div class="info-panel"><div class="card-top"><span class="tag"><?=htmlspecialchars($s['category'])?></span><span class="tag soft"><?=htmlspecialchars($s['course'])?></span><span class="tag <?=$st[1]?>"><?=$st[0]?></span></div><h2><?=htmlspecialchars($s['name'])?></h2><p class="department"><?=htmlspecialchars($s['department'])?></p><p><b>Eligibility</b><br><?=htmlspecialchars($s['eligibility'])?></p><p><b>Course / Level</b><br><?=htmlspecialchars($s['course'])?></p><p><b>Benefit</b><br><?=htmlspecialchars($s['benefit'])?></p><p><b>Deadline</b><br><?=!empty($s['deadline'])?htmlspecialchars(date('d F Y',strtotime($s['deadline']))):'Not provided'?></p><p><b>Required Documents</b><br><?=!empty($s['documents'])?nl2br(htmlspecialchars($s['documents'])):'Not provided yet. Check the official portal for the latest document requirements.'?></p><div class="card-actions"><a class="btn btn-primary" target="_blank" href="<?=htmlspecialchars($s['official_url'])?>">Open Official MahaDBT →</a><?php if(!empty($_SESSION['student_id'])):?><a class="btn favorite-btn <?=$saved?'favorite-saved':''?>" href="favorite.php?id=<?=$s['id']?>&back=<?=urlencode('scholarships.php?id='.$s['id'])?>"><span class="favorite-star"><?=$saved?'★':'☆'?></span><?=$saved?'Saved to Favourites':'Save to Favourites'?></a><?php else:?><a class="btn btn-light" href="login.php">Login to Save</a><?php endif;?><a class="btn btn-light" href="scholarships.php">← Back</a></div></div><?php else:?><form class="filter-bar"><input name="search" value="<?=htmlspecialchars($search)?>" placeholder="Search..."><select name="category"><option value="">All categories</option><?php foreach(['SC','ST','OBC','EWS','Minority','Disability','Merit'] as $c):?><option value="<?=$c?>" <?=$cat===$c?'selected':''?>><?=$c?></option><?php endforeach;?></select><select name="course"><option value="">All courses</option><?php foreach(['Post-Matric','Professional','Higher Education','Vocational','Technical','Medical'] as $c):?><option value="<?=$c?>" <?=$course===$c?'selected':''?>><?=$c?></option><?php endforeach;?></select><button class="btn btn-dark">Filter</button></form><div class="alert-grid"><div class="alert-box"><span class="eyebrow">NEWLY ADDED</span><h3>Latest scholarship updates</h3><ul><?php $latest=$pdo->query("SELECT name,created_at FROM scholarships ORDER BY created_at DESC,id DESC LIMIT 3")->fetchAll();foreach($latest as $n):?><li><b><?=htmlspecialchars($n['name'])?></b><small>Added <?=htmlspecialchars(date('d M Y',strtotime($n['created_at'])))?></small></li><?php endforeach;?></ul></div><div class="alert-box"><span class="eyebrow">DEADLINE ALERTS</span><h3>Closing soon</h3><ul><?php $soonQ=$pdo->query("SELECT name,deadline FROM scholarships WHERE deadline IS NOT NULL AND deadline>=CURDATE() AND deadline<=DATE_ADD(CURDATE(),INTERVAL 30 DAY) ORDER BY deadline LIMIT 5")->fetchAll();if($soonQ):foreach($soonQ as $n):?><li><b><?=htmlspecialchars($n['name'])?></b><small>Deadline <?=htmlspecialchars(date('d M Y',strtotime($n['deadline'])))?></small></li><?php endforeach;else:?><li>No closing-soon deadlines have been entered yet.</li><?php endif;?></ul></div></div><div class="results-row"><span><?=count($items)?> scholarships found</span><span>Official links open separately.</span></div><div class="card-grid"><?php foreach($items as $s):$st=scholarship_status($s['deadline']??null);$cardSaved=false;if(!empty($_SESSION['student_id'])){$fq=$pdo->prepare('SELECT id FROM student_favourites WHERE student_id=? AND scholarship_id=?');$fq->execute([$_SESSION['student_id'],$s['id']]);$cardSaved=(bool)$fq->fetch();}?><article class="scholarship-card"><div class="card-top"><span class="tag"><?=htmlspecialchars($s['category'])?></span><span class="tag soft"><?=htmlspecialchars($s['course'])?></span><span class="tag <?=$st[1]?>"><?=$st[0]?></span></div><h3><?=htmlspecialchars($s['name'])?></h3><p class="department"><?=htmlspecialchars($s['department'])?></p><p><b>Eligibility</b><br><?=htmlspecialchars($s['eligibility'])?></p><p><b>Benefit</b><br><?=htmlspecialchars($s['benefit'])?></p><?php if(!empty($s['deadline'])):?><p class="deadline-text">Deadline: <?=htmlspecialchars(date('d M Y',strtotime($s['deadline'])))?></p><?php endif;?><div class="card-actions"><a class="btn btn-small btn-light" href="scholarships.php?id=<?=$s['id']?>">View Details</a><?php if(!empty($_SESSION['student_id'])):?><a class="btn btn-small favorite-btn <?=$cardSaved?'favorite-saved':''?>" href="favorite.php?id=<?=$s['id']?>&back=<?=urlencode('scholarships.php'.($_SERVER['QUERY_STRING']?'?'.$_SERVER['QUERY_STRING']:''))?>"><span class="favorite-star"><?=$cardSaved?'★':'☆'?></span><?=$cardSaved?'Saved':'Save'?></a><?php endif;?><a class="btn btn-small btn-primary" target="_blank" href="<?=htmlspecialchars($s['official_url'])?>">Official ↗</a></div></article><?php endforeach;?></div><?php if(!$items):?><div class="empty">No scholarships found. Try another filter.</div><?php endif;?><?php endif;?></section><?php include 'includes/footer.php';?></body></html>
